:root {
  --bg: #1a1c2c;
  --card: #2a2d45;
  --accent: #41a6f6;
  --accent2: #f6c141;
  --text: #f4f4f4;
  --muted: #9a9db5;
  --danger: #f65741;
  --success: #41f67b;
  --radius: 8px;
  --font: 'Courier New', Courier, monospace;
}

* { box-sizing: border-box; margin: 0; padding: 0; }

body {
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  background: var(--bg);
  background-image: linear-gradient(45deg, #1a1c2c 25%, transparent 25%),
                    linear-gradient(-45deg, #1a1c2c 25%, transparent 25%),
                    linear-gradient(45deg, transparent 75%, #1a1c2c 75%),
                    linear-gradient(-45deg, transparent 75%, #1a1c2c 75%);
  background-size: 20px 20px;
  background-position: 0 0, 0 10px, 10px -10px, -10px 0px;
  font-family: var(--font);
  font-size: 18px;
  color: var(--text);
  padding: 16px;
}

.card {
  background: var(--card);
  border: 4px solid var(--accent);
  border-radius: var(--radius);
  box-shadow: 8px 8px 0 rgba(0,0,0,0.4);
  padding: 24px;
  width: 100%;
  max-width: 480px;
  display: flex;
  flex-direction: column;
  gap: 20px;
}

h1 {
  font-size: 1.5rem;
  text-align: center;
  letter-spacing: 2px;
  text-transform: uppercase;
  color: var(--accent2);
}

.display {
  font-size: clamp(2.5rem, 12vw, 4rem);
  text-align: center;
  letter-spacing: 4px;
  background: #14161f;
  border: 3px solid var(--accent);
  border-radius: var(--radius);
  padding: 16px 8px;
  color: var(--success);
  text-shadow: 0 0 8px rgba(65, 246, 123, 0.5);
  font-variant-numeric: tabular-nums;
  word-break: break-all;
}

.controls {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 12px;
}

.btn {
  font-family: var(--font);
  font-size: 1rem;
  padding: 14px 8px;
  border: 3px solid var(--accent);
  border-radius: var(--radius);
  background: #14161f;
  color: var(--text);
  cursor: pointer;
  text-transform: uppercase;
  letter-spacing: 1px;
  transition: transform 0.05s, background 0.15s, box-shadow 0.15s;
  box-shadow: 0 4px 0 #0b0c12;
}

.btn:hover:not(:disabled) {
  background: #1f2233;
  border-color: var(--accent2);
}

.btn:focus-visible {
  outline: 3px solid var(--accent2);
  outline-offset: 2px;
}

.btn:active:not(:disabled) {
  transform: translateY(4px);
  box-shadow: 0 0 0 #0b0c12;
}

.btn:disabled {
  opacity: 0.4;
  cursor: not-allowed;
  box-shadow: none;
}

.start { border-color: var(--success); }
.stop { border-color: var(--danger); }
.lap { border-color: var(--accent2); }
.reset { border-color: var(--muted); }

.laps {
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.laps h2 {
  font-size: 1.1rem;
  color: var(--accent2);
  text-transform: uppercase;
  letter-spacing: 1px;
}

.lap-list {
  list-style: none;
  max-height: 180px;
  overflow-y: auto;
  display: flex;
  flex-direction: column;
  gap: 6px;
  padding-right: 4px;
}

.lap-list li {
  display: flex;
  justify-content: space-between;
  background: #14161f;
  border-left: 4px solid var(--accent);
  padding: 8px 12px;
  font-variant-numeric: tabular-nums;
  border-radius: 4px;
}

.lap-list li span:first-child {
  color: var(--muted);
}

.lap-list li span:last-child {
  color: var(--success);
}

.lap-list:empty::after {
  content: 'No laps recorded';
  color: var(--muted);
  font-size: 0.9rem;
  font-style: italic;
}

@media (max-width: 400px) {
  .card { padding: 16px; }
  .display { letter-spacing: 2px; }
}

(function () {
  'use strict';

  let startTime = 0;
  let elapsed = 0;
  let running = false;
  let rafId = null;
  let laps = [];

  const display = document.getElementById('display');
  const startBtn = document.getElementById('startBtn');
  const stopBtn = document.getElementById('stopBtn');
  const lapBtn = document.getElementById('lapBtn');
  const resetBtn = document.getElementById('resetBtn');
  const lapList = document.getElementById('lapList');

  function format(ms) {
    const totalCs = Math.floor(ms / 10);
    const cs = totalCs % 100;
    const totalSec = Math.floor(totalCs / 100);
    const sec = totalSec % 60;
    const min = Math.floor(totalSec / 60);
    return String(min).padStart(2, '0') + ':' +
           String(sec).padStart(2, '0') + '.' +
           String(cs).padStart(2, '0');
  }

  function currentElapsed() {
    return running ? elapsed + (performance.now() - startTime) : elapsed;
  }

  function render() {
    display.textContent = format(currentElapsed());
    if (running) {
      rafId = requestAnimationFrame(render);
    }
  }

  function updateButtons() {
    startBtn.disabled = running;
    stopBtn.disabled = !running;
    lapBtn.disabled = !running;
    resetBtn.disabled = running || (elapsed === 0 && laps.length === 0);
  }

  function start() {
    if (running) return;
    running = true;
    startTime = performance.now();
    updateButtons();
    render();
  }

  function stop() {
    if (!running) return;
    elapsed += performance.now() - startTime;
    running = false;
    if (rafId) cancelAnimationFrame(rafId);
    rafId = null;
    display.textContent = format(elapsed);
    updateButtons();
  }

  function lap() {
    if (!running) return;
    const time = currentElapsed();
    const prev = laps.length ? laps[laps.length - 1].time : 0;
    laps.push({ index: laps.length + 1, time: time, split: time - prev });
    renderLaps();
    updateButtons();
  }

  function reset() {
    if (running) {
      stop();
    }
    elapsed = 0;
    laps = [];
    display.textContent = format(0);
    renderLaps();
    updateButtons();
  }

  function renderLaps() {
    lapList.innerHTML = '';
    laps.forEach(function (lap) {
      const li = document.createElement('li');
      const label = document.createElement('span');
      label.textContent = 'Lap ' + lap.index;
      const value = document.createElement('span');
      value.textContent = format(lap.time) + ' (+' + format(lap.split) + ')';
      li.appendChild(label);
      li.appendChild(value);
      lapList.appendChild(li);
    });
  }

  startBtn.addEventListener('click', start);
  stopBtn.addEventListener('click', stop);
  lapBtn.addEventListener('click', lap);
  resetBtn.addEventListener('click', reset);

  document.addEventListener('keydown', function (e) {
    if (e.target.tagName === 'BUTTON') return;
    if (e.code === 'Space') {
      e.preventDefault();
      if (running) stop(); else start();
    } else if (e.code === 'KeyL') {
      lap();
    } else if (e.code === 'KeyR') {
      reset();
    }
  });

  display.textContent = format(0);
  updateButtons();
})();
